def solve(grid):
    # Find the two non‑zero colours.  
    non_zero = set()
    for row in grid:
        for v in row:
            if v:
                non_zero.add(v)
    if len(non_zero) != 2:
        return grid                       # safety guard

    rows, cols = len(grid), len(grid[0])

    # ------------------------------------------------------------
    # Determine which colour is the block (has a neighbour of the same colour)
    # and which is the line colour.
    # ------------------------------------------------------------
    block_colour = line_colour = None

    for colour in non_zero:
        has_neighbour = False
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == colour:
                    if i > 0   and grid[i-1][j] == colour: has_neighbour = True
                    if i+1 < rows and grid[i+1][j] == colour: has_neighbour = True
                    if j > 0   and grid[i][j-1] == colour: has_neighbour = True
                    if j+1 < cols and grid[i][j+1] == colour: has_neighbour = True
                    if has_neighbour:
                        break
            if has_neighbour:
                break
        if has_neighbour:
            block_colour = colour
        else:
            line_colour = colour

    # If the neighbour detection failed (should not happen in the given tasks),
    # fall back to the colour that occurs more often.
    if block_colour is None or line_colour is None:
        from collections import Counter
        cnt = Counter(v for row in grid for v in row if v)
        block_colour = max(cnt, key=cnt.get)
        line_colour = [c for c in cnt if c != block_colour][0]

    # ------------------------------------------------------------
    # Bounding box of the block colour
    # ------------------------------------------------------------
    min_r = rows
    max_r = -1
    min_c = cols
    max_c = -1
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == block_colour:
                if i < min_r: min_r = i
                if i > max_r: max_r = i
                if j < min_c: min_c = j
                if j > max_c: max_c = j

    # ------------------------------------------------------------
    # For every column that belongs to the block, fill the cells below
    # the lowest block cell when a line‑colour cell exists lower down.
    # ------------------------------------------------------------
    for c in range(min_c, max_c + 1):
        # lowest block cell in this column
        max_block_row = -1
        for r in range(min_r, max_r + 1):
            if grid[r][c] == block_colour:
                max_block_row = r
        if max_block_row == -1:          # no block in this column (should not happen)
            continue

        # Is there any line‑colour cell below the block in this column?
        has_line_below = any(grid[r][c] == line_colour
                             for r in range(max_block_row + 1, rows))

        if has_line_below:
            # fill every empty cell below the block with the line colour
            for r in range(max_block_row + 1, rows):
                if grid[r][c] == 0:
                    grid[r][c] = line_colour

    return grid

